def clone(url, dest=None, depth=None):
    if dest and os.path.exists(dest):
        raise FileExistsError('Destination already exists: %s' % dest)
    dest = dest if dest else tempdir()
    cmd = ['git', 'clone', url, dest]
    if depth:
        cmd += ['--depth', depth]
    process.call(cmd)
    return dest

